toolCalls.args:
{"command": "SDK_VERSION=$(./.dotnet/dotnet --version)
# Create global.json
cat > global.json <<EOF
{
  "sdk": {
    "version": "$SDK_VERSION",
    "allowPrerelease": true,
    "rollForward": "latestFeature",
    "paths": [".dotnet", "\$host\$"]
  }
}
EOF
# Update .gitignore
grep -qxF '.dotnet/' .gitignore 2>/dev/null || printf '.dotnet/\n' >> .gitignore
echo "=== global.json ===" && cat global.json && echo && echo "=== Verify ===" && dotnet --version", "description": "Create global.json and update .gitignore"}

